// 计算一组数据的最少操作次数
long long solveOne(int n, const vector<long long>& a, const vector<long long>& b) {
    // needA 表示数组 a 还需要单独减少的总量
    long long needA = 0;
    // needB 表示数组 b 还需要单独减少的总量
    long long needB = 0;

    // 逐位比较 a 和 b
    for (int i = 0; i < n; i++) {
        if (a[i] > b[i]) {
            // a[i] 多出来的部分最终必须减掉
            needA += a[i] - b[i];
        } else {
            // b[i] 多出来的部分最终必须减掉
            needB += b[i] - a[i];
        }
    }

    // 最少操作次数等于两边需求的较大值
    return max(needA, needB);
}

